MOD = 1 << 64


def fp(data):
    h = 0
    for c in data:
        h = (h * 257 + c + 1) % MOD
    return {'n': len(data), 'h': '%016x' % h}


def action_bytes(at, stream, kind, data, end):
    out = at.to_bytes(8, 'big') + stream.to_bytes(4, 'big') + kind.encode('ascii')
    if kind in ('H', 'h'):
        out += len(data).to_bytes(8, 'big')
        for n, v in data:
            out += len(n).to_bytes(8, 'big') + n
            out += len(v).to_bytes(8, 'big') + v
    else:
        out += len(data).to_bytes(8, 'big') + data
    return out + bytes((1 if end else 0,))


def field_fp(fields):
    out = bytearray()
    out += len(fields).to_bytes(8, 'big')
    for n, v in fields:
        out += len(n).to_bytes(8, 'big') + n
        out += len(v).to_bytes(8, 'big') + v
    return fp(bytes(out))


def expected(doc):
    cases = doc['cases']
    frames = []
    for case in cases:
        rows = []
        for frame in case['frames']:
            kind = frame['Type']
            if kind == 'headers':
                if 'headers_kv' in frame:
                    pairs = [[k, v.encode()] for k, v in frame['headers_kv'].items()]
                else:
                    pairs = [[p[0].encode(), p[1].encode()] for p in frame['data_to_transfered']]
                rows.append({'Type': 'headers', 'data_to_transfered': pairs,
                             'End_Stream': frame.get('End_Stream', False)})
            elif kind == 'sleep':
                rows.append({'Type': 'sleep', 'Time_to_Stop': frame['Time_to_Stop']})
            else:
                rows.append({'Type': kind,
                             'data_to_transfered': frame['data_to_transfered'].encode(),
                             'End_Stream': frame.get('End_Stream', True)})
        frames.append(rows)
    events = []
    for ev in doc['events']:
        row = {'kind': ev['kind'], 'at': ev['at']}
        if ev['kind'] == 'headers':
            row['stream'] = ev['stream']
            row['end'] = ev['end']
            row['fields'] = [[p[0].encode(), p[1].encode()] for p in ev['fields']]
        elif ev['kind'] == 'data':
            row['stream'] = ev['stream']
            row['end'] = ev['end']
            row['data'] = ev['data'].encode()
        events.append(row)
    replayed = simulate(frames, events, doc['timeout_ms'])
    records = []
    for row in replayed:
        sent = b''.join(action_bytes(t, row['stream'], k, d, e) for t, k, d, e in row['sent'])
        received = b''.join(action_bytes(t, row['stream'], k, d, e) for t, k, d, e in row['received'])
        body = b''.join(row['body'])
        records.append({'name': row['name'], 'stream': row['stream'],
                        'state': row['state'], 'at': row['at'], 'frames': row['frames'],
                        'request_frames': row['request_frames'],
                        'payload_bytes': row['payload_bytes'], 'sent': fp(sent),
                        'received': fp(received), 'response_frames': row['response_frames'],
                        'response_body': fp(body), 'origin_count': 0, 'flags': []})
    channels_out = []
    owner_seen = {}
    origin = {case['name']: 0 for case in cases}
    case_flags = {case['name']: set() for case in cases}
    request_frames = {case['name']: rec['request_frames']
                      for case, rec in zip(cases, records)}
    expect = {case['name']: case['expect'] for case in cases}
    for channel in doc['channels']:
        labels = [part['case'] for part in channel['parts']]
        chunks = [part['data'].encode() for part in channel['parts']]
        data = b''.join(chunks)
        bounds = [0]
        for chunk in chunks:
            bounds.append(bounds[-1] + len(chunk))
        reqs, error = parse(data)
        ends = [r['end'] for r in reqs]
        committed = []
        for bound in bounds[1:]:
            count = 0
            for end in ends:
                if end <= bound:
                    count += 1
            committed.append(count)
        out_reqs = []
        for r in reqs:
            segs = []
            for j, chunk in enumerate(chunks):
                low = max(r['start'], bounds[j])
                high = min(r['end'], bounds[j + 1])
                if high > low:
                    if segs and segs[-1][0] == labels[j]:
                        segs[-1][1] += high - low
                    else:
                        segs.append([labels[j], high - low])
            owner = None
            for j, chunk in enumerate(chunks):
                if bounds[j] <= r['start'] < bounds[j + 1]:
                    owner = labels[j]
                    break
            flags = set()
            if owner is None:
                flags.add('unattributed')
            if any(label != owner for label, _ in segs):
                flags.add('mixed_owner')
            if r['host_count'] == 0:
                flags.add('missing_host')
            elif r['host_count'] > 1:
                flags.add('multiple_host')
            if owner is not None:
                exp = expect[owner]
                if (r['method'] != exp['method'].encode()
                        or r['target'] != exp['target'].encode()
                        or r['host_count'] != 1
                        or r['host'].lower() != exp['host'].encode().lower()):
                    flags.add('identity')
                owner_seen[owner] = owner_seen.get(owner, 0) + 1
                if owner_seen[owner] > 1:
                    flags.add('extra')
                if request_frames[owner] == 0:
                    flags.add('unsent')
                origin[owner] += 1
                if 'identity' in flags:
                    case_flags[owner].add('identity')
                if 'mixed_owner' in flags:
                    case_flags[owner].add('mixed_origin')
            out_reqs.append({'start': r['start'], 'end': r['end'],
                             'method': fp(r['method']), 'target': fp(r['target']),
                             'host': fp(r['host']), 'host_count': r['host_count'],
                             'headers': field_fp(r['fields']), 'body': fp(r['body']),
                             'trailers': field_fp(r['trailers']), 'framing': r['framing'],
                             'owner': owner, 'owners': segs, 'flags': sorted(flags)})
        channels_out.append({'name': channel['name'], 'bytes': fp(data),
                             'requests': out_reqs, 'committed': committed,
                             'error': error})
    for case, record in zip(cases, records):
        name = case['name']
        count = origin[name]
        flags = set(case_flags[name])
        if record['request_frames'] > 0 and count == 0:
            flags.add('missing_origin')
        if count > 1:
            flags.add('extra_origin')
        if count > 0 and record['request_frames'] == 0:
            flags.add('unsent_origin')
        record['origin_count'] = count
        record['flags'] = sorted(flags)
    return {'cases': records, 'channels': channels_out}


NAMES = 'abcdefghijklmnopqrstuvwxyz'


def rand_name(rng, used):
    while True:
        n = ''.join(rng.choice(NAMES) for _ in range(rng.randrange(1, 6)))
        if n not in used:
            used.add(n)
            return n


def gen_document(rng):
    used = set()
    doc = {'seed': ''.join(rng.choice(NAMES) for _ in range(rng.randrange(0, 5))),
           'definitions': [], 'timeout_ms': rng.randrange(1, 30),
           'cases': [], 'events': [], 'channels': []}
    cases = []
    for _ in range(rng.randrange(0, 4)):
        name = rand_name(rng, used)
        frames = []
        for _ in range(rng.randrange(0, 6)):
            kind = rng.choice(['headers', 'data', 'datagram', 'sleep'])
            if kind == 'headers':
                if rng.random() < 0.5:
                    frame = {'Type': 'headers',
                             'headers_kv': {rand_name(rng, set()): rng.choice(['a', 'b', ':path', 'x'*3])}}
                else:
                    frame = {'Type': 'headers',
                             'data_to_transfered': [[rng.choice([':method', 'a', 'host']),
                                                     rng.choice(['GET', 'POST', '/x'])]
                                                    for _ in range(rng.randrange(1, 4))]}
                if rng.random() < 0.4:
                    frame['End_Stream'] = rng.random() < 0.6
            elif kind == 'sleep':
                frame = {'Type': 'sleep', 'Time_to_Stop': rng.randrange(0, 12)}
            else:
                frame = {'Type': kind, 'data_to_transfered': rng.choice(['', 'abc', 'xyz'*3])}
                if rng.random() < 0.4:
                    frame['End_Stream'] = rng.random() < 0.6
            frames.append(frame)
        cases.append({'name': name, 'frames': frames,
                      'expect': {'method': rng.choice(['GET', 'POST']),
                                 'target': rng.choice(['/a', '/bb']),
                                 'host': rng.choice(['h.example', 'other')}})
    doc['cases'] = cases
    names = [c['name'] for c in cases]
    for _ in range(rng.randrange(0, 6)):
        kind = rng.choice(['headers', 'data', 'close'])
        if kind == 'close':
            doc['events'].append({'at': rng.randrange(0, 40), 'kind': 'close'})
        elif kind == 'headers':
            doc['events'].append({'at': rng.randrange(0, 40), 'kind': 'headers',
                                  'stream': rng.randrange(0, 16),
                                  'fields': [[rng.choice([':status', 'x']), rng.choice(['200', 'zz'])]
                                             for _ in range(rng.randrange(1, 3))],
                                  'end': rng.random() < 0.6})
        else:
            doc['events'].append({'at': rng.randrange(0, 40), 'kind': 'data',
                                  'stream': rng.randrange(0, 16),
                                  'data': rng.choice(['', 'p', 'qq']),
                                  'end': rng.random() < 0.6})
    for _ in range(rng.randrange(0, 3)):
        parts = []
        for _ in range(rng.randrange(1, 5)):
            owner = rng.choice(names + [None]) if names else None
            parts.append({'case': owner, 'data': gen_http(rng, names)})
        doc['channels'].append({'name': rand_name(rng, set()), 'parts': parts})
    return doc


def gen_http(rng, names):
    """Random HTTP/1.1-ish capture bytes."""
    out = b''
    for _ in range(rng.randrange(0, 4)):
        style = rng.randrange(0, 8)
        method = rng.choice([b'GET', b'POST', b'PUT'])
        target = rng.choice([b'/', b'/a', b'/x?q=1'])
        if style == 0:
            host = rng.choice([b'h.example', b'other', b'EXAMPLE'])
            out += method + b' ' + target + b' HTTP/1.1\r\nHost: ' + host + b'\r\n\r\n'
        elif style == 1:
            out += method + b' ' + target + b' HTTP/1.1\r\nHost: h.example\r\nContent-Length: 3\r\n\r\nabc'
        elif style == 2:
            out += method + b' ' + target + b' HTTP/1.1\r\nHost: h.example\r\nTransfer-Encoding: chunked\r\n\r\n'
            out += b'2\r\nab\r\n0\r\n\r\n'
        elif style == 3:
            out += method + b' ' + target + b' HTTP/1.1\r\nHost: h.example\r\nTransfer-Encoding: chunked\r\n\r\n'
            out += b'3;ext\r\nxyz\r\n0\r\nX: 1\r\n\r\n'
        elif style == 4:
            out += method + b' ' + target + b' HTTP/1.1\r\nhost: h.example\r\nContent-Length: 0\r\n\r\n'
        elif style == 5:
            out += rng.choice([b'junk\r\n', b'GET /\r\n', b'GET / HTTP/1.0\r\n\r\n',
                               b'GET  / HTTP/1.1\r\n\r\n', b'GET / HTTP/1.1\r\nBad: v\x01\r\n\r\n',
                               b'GET / HTTP/1.1\r\nHost: x\r\nContent-Length: 5, 5\r\n\r\nab',
                               b'GET / HTTP/1.1\r\nHost: x\r\nTransfer-Encoding: Chunked\r\n\r\n1\r\na\r\n0\r\n\r\n'])
        elif style == 6:
            out += (method + b' ' + target + b' HTTP/1.1\r\nHost: h.example\r\n'
                    + b'X: 1\r\n' * rng.randrange(0, 3) + b'\r\n')
        else:
            out += rng.choice([b'', b'GET / HTTP/1.1\r\n', b'x', b'\r\n', b'GET / HTTP/1.1\r\nHost:\r\n\r\n'])
    if rng.random() < 0.2:
        out += rng.choice([b'GET / HTTP/1.1\r\nHost: p\r\n', b'GET / HTTP/1.1\r\nContent-Length: 4\r\n\r\nab'])
    return out.decode('latin1').encode('latin1').decode('latin1')
